WITH flattened_attrs AS (SELECT id, plan, effective_from, tier_limits, tier_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT id, plan, CUME_DIST() OVER w_ordered AS lowest_price_cume_dist, LAG(entry_price, 2) OVER (PARTITION BY MONTH(effective_from), plan ORDER BY lowest_price, id) AS prev_entry_price, COUNT(avg_tier_price) OVER w_part AS effective_from_year_count_avg_tier_price FROM flattened_attrs WHERE plan != 'starter' WINDOW w_ordered AS (PARTITION BY plan ORDER BY lowest_price DESC), w_part AS (PARTITION BY YEAR(effective_from));
